 * Prefix index over Unicode strings.
 *
 * A real trie: one node per distinct prefix, walked by Unicode code point.
 * Each node keeps a per-node count of stored words below it so prefix
 * counts cost only the length of the prefix.
 */

class TrieNode {
  /** @type {Map<string, TrieNode>} */
  children = new Map();

  /** Whether this node represents a stored word. */
  isWord = false;

  /** Value stored at this node, when isWord is true. */
  value = undefined;

  /** Number of stored words at or below this node. */
  count = 0;
}

/**
 * Splits a string into an array of its Unicode code points as strings.
 * @param {string} str String to split.
 * @returns {string[]} Array of code point strings.
 */
function toCodePoints(str) {
  return Array.from(str);
}

export class Trie {
  /** @type {TrieNode} */
  #root = new TrieNode();

  /** Total number of nodes, the root included. */
  #nodeCount = 1;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#root.count;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#nodeCount;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const chars = toCodePoints(word);
    let node = this.#root;
    let isNew = false;
    node.count += 1;
    for (const ch of chars) {
      let child = node.children.get(ch);
      if (!child) {
        child = new TrieNode();
        node.children.set(ch, child);
        this.#nodeCount += 1;
      }
      node = child;
      node.count += 1;
    }
    if (!node.isWord) {
      node.isWord = true;
      isNew = true;
    }
    const previous = isNew ? undefined : node.value;
    node.value = value;
    return previous;
  }

  /**
   * Walks to the node for a word, or returns null if the path doesn't exist.
   * @param {string} word Word to walk.
   * @returns {TrieNode | null} The node, or null.
   */
  #walk(word) {
    let node = this.#root;
    for (const ch of toCodePoints(word)) {
      const child = node.children.get(ch);
      if (!child) return null;
      node = child;
    }
    return node;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const node = this.#walk(word);
    return node && node.isWord ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const node = this.#walk(word);
    return !!(node && node.isWord);
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const chars = toCodePoints(word);
    const path = [this.#root];
    let node = this.#root;
    for (const ch of chars) {
      const child = node.children.get(ch);
      if (!child) return false;
      path.push(child);
      node = child;
    }
    if (!node.isWord) return false;
    node.isWord = false;
    node.value = undefined;
    for (const n of path) n.count -= 1;
    // Prune dead nodes from the end back toward the root.
    for (let i = path.length - 1; i > 0; i -= 1) {
      const current = path[i];
      if (current.count === 0 && current.children.size === 0) {
        const parent = path[i - 1];
        parent.children.delete(chars[i - 1]);
        this.#nodeCount -= 1;
      } else {
        break;
      }
    }
    return true;
  }

  /**
   * Counts the stored words that start with a prefix.
   * @param {string} prefix Prefix to count under.
   * @returns {number} Number of words with that prefix.
   */
  countPrefix(prefix) {
    if (typeof prefix !== 'string') throw new TypeError('prefix must be a string');
    const node = this.#walk(prefix);
    return node ? node.count : 0;
  }

  /**
   * Collects [word, value] pairs under a node, in code point order.
   * @param {TrieNode} node Node to start from.
   * @param {string} prefix Prefix accumulated so far.
   * @param {number} limit Maximum number of results to collect.
   * @param {Array<[string, unknown]>} out Accumulator.
   */
  #collect(node, prefix, limit, out) {
    if (out.length >= limit) return;
    if (node.isWord) {
      out.push([prefix, node.value]);
      if (out.length >= limit) return;
    }
    const keys = [...node.children.keys()].sort((a, b) => a.codePointAt(0) - b.codePointAt(0));
    for (const key of keys) {
      this.#collect(node.children.get(key), prefix + key, limit, out);
      if (out.length >= limit) return;
    }
  }

  /**
   * Lists the stored words that start with a prefix, in code point order.
   * @param {string} prefix Prefix to search under.
   * @param {number} [limit] Maximum number of words to return.
   * @returns {string[]} Matching words.
   */
  search(prefix, limit = Number.POSITIVE_INFINITY) {
    if (typeof prefix !== 'string') throw new TypeError('prefix must be a string');
    if (limit !== Number.POSITIVE_INFINITY && !(Number.isInteger(limit) && limit >= 0 && Number.isSafeInteger(limit))) {
      throw new TypeError('limit must be a non-negative integer');
    }
    const node = this.#walk(prefix);
    if (!node || limit === 0) return [];
    const out = [];
    this.#collect(node, prefix, limit, out);
    return out.map(([word]) => word);
  }

  /**
   * Lists every stored word with its value, in code point order.
   * @returns {Array<[string, unknown]>} Word and value pairs.
   */
  entries() {
    const out = [];
    this.#collect(this.#root, '', Number.POSITIVE_INFINITY, out);
    return out;
  }

  /**
