}","new_string":"  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    if (typeof command !== 'object' || command === null) throw new TypeError('command must be an object');
    if (!COMMAND_TYPES.includes(command.type)) throw new TypeError(`unknown command type: ${command.type}`);
    if (!isNonEmptyString(command.commandId)) throw new TypeError('command must carry a non-empty commandId');
    if (!isIntAtLeast(command.at, 0)) throw new TypeError('command must carry a non-negative integer at');

    if (this.#resultsById.has(command.commandId)) {
      const recorded = this.#resultsById.get(command.commandId);
      return { ...recorded, replayed: true };
    }

    const from = this.#state;

    // Clock check.
    if (command.at < this.#clockMs) {
      const entry = {
        seq: this.#audit.length + 1,
        commandId: command.commandId,
        type: command.type,
        at: this.#clockMs,
        from,
        to: from,
        ok: false,
        code: 'CLOCK_REGRESSION',
      };
      this.#audit.push(entry);
      const result = {
        ok: false,
        code: 'CLOCK_REGRESSION',
        message: 'command time precedes the order clock',
        state: this.#state,
        seq: entry.seq,
        replayed: false,
      };
      this.#resultsById.set(command.commandId, result);
      return { ...result };
    }

    this.#clockMs = command.at;

    const fail = (code, message) => {
      const entry = {
        seq: this.#audit.length + 1,
        commandId: command.commandId,
        type: command.type,
        at: command.at,
        from,
        to: from,
        ok: false,
        code,
      };
      this.#audit.push(entry);
      const result = { ok: false, code, message, state: this.#state, seq: entry.seq, replayed: false };
      this.#resultsById.set(command.commandId, result);
      return { ...result };
    };

    // State check.
    if (!allowedTypes(from).includes(command.type)) {
      return fail('BAD_STATE', `${command.type} is not allowed in state ${from}`);
    }

    // Field checks.
    switch (command.type) {
      case 'addItem': {
        if (!isNonEmptyString(command.sku)) return fail('MISSING_FIELD', 'sku is required');
        if (!isIntAtLeast(command.qty, 1)) return fail('BAD_AMOUNT', 'qty must be an integer of at least 1');
        if (!isIntAtLeast(command.unitPriceCents, 0)) {
          return fail('BAD_AMOUNT', 'unitPriceCents must be a non-negative integer');
        }
        break;
      }
      case 'removeItem': {
        if (!isNonEmptyString(command.sku)) return fail('MISSING_FIELD', 'sku is required');
        break;
      }
      case 'pay': {
        if (!isIntAtLeast(command.amountCents, 0)) {
          return fail('BAD_AMOUNT', 'amountCents must be a non-negative integer');
        }
        break;
      }
      case 'ship': {
        if (!isNonEmptyString(command.carrier)) return fail('MISSING_FIELD', 'carrier is required');
        if (!isNonEmptyString(command.tracking)) return fail('MISSING_FIELD', 'tracking is required');
        break;
      }
      case 'cancel': {
        if (!isNonEmptyString(command.reason)) return fail('MISSING_FIELD', 'reason is required');
        break;
      }
      case 'refund': {
        if (!isIntAtLeast(command.amountCents, 1)) {
          return fail('BAD_AMOUNT', 'amountCents must be an integer of at least 1');
        }
        break;
      }
      default:
        break;
    }

    // Business guards.
    switch (command.type) {
      case 'addItem': {
        if (this.#items.has(command.sku)) return fail('DUPLICATE_SKU', `${command.sku} is already on the order`);
        break;
      }
      case 'removeItem': {
        if (!this.#items.has(command.sku)) return fail('NO_SUCH_ITEM', `${command.sku} is not on the order`);
        break;
      }
      case 'pay': {
        if (this.#items.size === 0) return fail('EMPTY_ORDER', 'an order with no items cannot be paid');
        if (command.amountCents !== this.totalCents) {
          return fail('AMOUNT_MISMATCH', 'amountCents must equal the order total');
        }
        break;
      }
      case 'refund': {
        if (command.amountCents > this.#paidCents - this.#refundedCents) {
          return fail('REFUND_TOO_LARGE', 'amountCents exceeds the amount still refundable');
        }
        break;
      }
      default:
        break;
    }

    // Effects.
    switch (command.type) {
      case 'addItem': {
        this.#items.set(command.sku, {
          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        break;
      }
      case 'removeItem': {
        this.#items.delete(command.sku);
        break;
      }
      case 'pay': {
        this.#paidCents = command.amountCents;
        this.#state = 'paid';
        break;
      }
      case 'pack': {
        this.#state = 'packed';
        break;
      }
      case 'ship': {
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        this.#state = 'shipped';
        break;
      }
      case 'deliver': {
        this.#deliveredAt = command.at;
        this.#state = 'delivered';
        break;
      }
      case 'cancel': {
        this.#refundedCents = this.#paidCents;
        this.#state = 'cancelled';
        break;
      }
      case 'refund': {
        this.#refundedCents += command.amountCents;
        if (this.#refundedCents >= this.#paidCents) this.#state = 'refunded';
        break;
      }
      default:
        break;
    }

    const entry = {
      seq: this.#audit.length + 1,
      commandId: command.commandId,
      type: command.type,
      at: command.at,
      from,
      to: this.#state,
      ok: true,
    };
    this.#audit.push(entry);
    const result = { ok: true, state: this.#state, seq: entry.seq, replayed: false };
    this.#resultsById.set(command.commandId, result);
    return { ...result };
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) throw new TypeError('commands must be an array');
    const order = new Order(init);
    for (const command of commands) order.apply(command);
    return order;
  }
}"}

