        if (!this.#items.has(command.sku)) return fail('NO_SUCH_ITEM', `${command.sku} is not on the order`);
        break;
      }
      case 'pay': {
        if (this.#items.size === 0) return fail('EMPTY_ORDER', 'an order with no items cannot be paid');
        if (command.amountCents !== this.totalCents) {
          return fail('AMOUNT_MISMATCH', 'amountCents must equal the order total');
        }
        break;
      }
      case 'refund': {
        if (command.amountCents > this.#paidCents - this.#refundedCents) {
          return fail('REFUND_TOO_LARGE', 'amountCents exceeds the amount still refundable');
        }
        break;
      }
      default:
        break;
    }

    // Effects.
    switch (command.type) {
      case 'addItem': {
        this.#items.set(command.sku, {
          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        break;
      }
      case 'removeItem': {
        this.#items.delete(command.sku);
        break;
      }
      case 'pay': {
        this.#paidCents = command.amountCents;
        this.#state = 'paid';
        break;
      }
      case 'pack': {
        this.#state = 'packed';
        break;
      }
      case 'ship': {
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        this.#state = 'shipped';
        break;
      }
      case 'deliver': {
        this.#deliveredAt = command.at;
        this.#state = 'delivered';
        break;
      }
      case 'cancel': {
        this.#refundedCents = this.#paidCents;
        this.#state = 'cancelled';
        break;
      }
      case 'refund': {
        this.#refundedCents += command.amountCents;
        if (this.#refundedCents >= this.#paidCents) this.#state = 'refunded';
        break;
      }
      default:
        break;
    }

    const entry = {
      seq: this.#audit.length + 1,
      commandId: command.commandId,
      type: command.type,
      at: command.at,
      from,
      to: this.#state,
      ok: true,
    };
    this.#audit.push(entry);
    const result = { ok: true, state: this.#state, seq: entry.seq, replayed: false };
    this.#resultsById.set(command.commandId, result);
    return { ...result };
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) throw new TypeError('commands must be an array');
    const order = new Order(init);
    for (const command of commands) order.apply(command);
    return order;
  }
}"}

