/**
 * Deep-clone a JSON-shaped value, treating keys that shadow
 * `Object.prototype` (like `__proto__`) as ordinary own properties.
 *
 * @param {unknown} value the value to clone
 * @returns {unknown} an independent copy
 */
export function cloneJSON(value) {
  if (value === null || typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map(cloneJSON);
  const result = {};
  for (const key of Object.keys(value)) {
    Object.defineProperty(result, key, {
      value: cloneJSON(value[key]),
      writable: true,
      enumerable: true,
      configurable: true,
    });
  }
  return result;
}

/**
 * Check whether a value is valid JSON data: no `undefined`, functions,
 * symbols, non-finite numbers, or non-plain objects.
 *
 * @param {unknown} value the value to check
 * @returns {boolean} whether the value (recursively) is JSON data
 */
export function isJsonData(value) {
  if (value === null) return true;
  const type = typeof value;
  if (type === 'boolean' || type === 'string') return true;
  if (type === 'number') return Number.isFinite(value);
  if (type !== 'object') return false;
  if (Array.isArray(value)) return value.every((item) => isJsonData(item));
  const proto = Object.getPrototypeOf(value);
  if (proto !== Object.prototype && proto !== null) return false;
  return Object.keys(value).every((key) => isJsonData(value[key]));
}

/**
 * Compare two JSON values for structural equality: object members in any
 * order, array elements in order, and no type coercion.
 *
 * @param {unknown} a first value
 * @param {unknown} b second value
 * @returns {boolean} whether the two values are structurally equal
 */
export function jsonEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (a === null || b === null) return false;
  if (typeof a !== 'object') return false;
  const aIsArray = Array.isArray(a);
  const bIsArray = Array.isArray(b);
  if (aIsArray !== bIsArray) return false;
  if (aIsArray) {
    if (a.length !== b.length) return false;
    return a.every((item, index) => jsonEqual(item, b[index]));
  }
  const aKeys = Object.keys(a);
  const bKeys = Object.keys(b);
  if (aKeys.length !== bKeys.length) return false;
  return aKeys.every(
    (key) => Object.prototype.hasOwnProperty.call(b, key) && jsonEqual(a[key], b[key]),
  );
