   * @param {{ cause?: unknown }} [options] the underlying pointer failure, when there is one
   */
  constructor(message, index, options) {
    super(message, options);
    this.name = 'PatchError';
    this.index = index;
  }
}

const OPS = new Set(['add', 'remove', 'replace', 'move', 'copy', 'test']);

/**
 * Define an own data property, safe even for keys (like `__proto__`) that
 * would otherwise be intercepted by an accessor on `Object.prototype`.
 *
 * @param {object} target the object to modify
 * @param {string} key the property name
 * @param {unknown} value the property value
 */
function setProperty(target, key, value) {
  Object.defineProperty(target, key, {
    value,
    writable: true,
    enumerable: true,
    configurable: true,
  });
}

/**
 * Check that an operation carries the members its `op` requires, before
 * anything runs.
 *
 * @param {unknown} operation the raw operation
 */
function validateOperation(operation) {
  if (typeof operation !== 'object' || operation === null) {
    throw new Error('operation must be an object');
  }
  const { op } = operation;
  if (!OPS.has(op)) {
    throw new Error(`unknown operation: ${op}`);
  }
  if (!('path' in operation)) {
    throw new Error(`${op} requires a path`);
  }
  if ((op === 'add' || op === 'replace' || op === 'test') && !('value' in operation)) {
    throw new Error(`${op} requires a value`);
  }
  if ((op === 'move' || op === 'copy') && !('from' in operation)) {
    throw new Error(`${op} requires a from`);
  }
}

/**
 * Check that a value is JSON data, for values supplied by a patch operation.
 *
 * @param {unknown} value the value to check
 * @returns {unknown} the same value, when it is valid
 */
function checkValue(value) {
  if (!isJsonData(value)) {
    throw new Error('value is not JSON data');
  }
  return value;
}

/**
 * Add (or overwrite) a value at a pointer, inserting before an array index.
 *
 * @param {unknown} root the document to mutate
 * @param {string} path pointer to add at
 * @param {unknown} value the (already cloned) value to insert
 * @returns {unknown} the (possibly new) root
 */
function performAdd(root, path, value) {
  const tokens = parsePointer(path);
  if (tokens.length === 0) return value;
  const token = tokens[tokens.length - 1];
  const parentPointer = formatPointer(tokens.slice(0, -1));
  const parent = resolve(root, parentPointer);
  const fullPointer = formatPointer(tokens);
  if (Array.isArray(parent)) {
    let index;
    if (token === '-') {
      index = parent.length;
    } else if (ARRAY_INDEX.test(token)) {
      index = Number(token);
      if (index > parent.length) {
        throw new PointerError(`index out of range: ${token} at ${fullPointer}`, fullPointer);
      }
    } else {
      throw new PointerError(`invalid array index: ${token} at ${fullPointer}`, fullPointer);
    }
    parent.splice(index, 0, value);
  } else if (parent !== null && typeof parent === 'object') {
    setProperty(parent, token, value);
  } else {
    throw new PointerError(`cannot index into ${typeName(parent)} at ${fullPointer}`, fullPointer);
  }
  return root;
}

/**
 * Remove the value at a pointer, which must already exist.
 *
 * @param {unknown} root the document to mutate
 * @param {string} path pointer to remove
 * @returns {unknown} the root
 */
function performRemove(root, path) {
  const tokens = parsePointer(path);
  if (tokens.length === 0) {
    throw new Error('cannot remove the whole document');
  }
  resolve(root, path);
  const token = tokens[tokens.length - 1];
  const parentPointer = formatPointer(tokens.slice(0, -1));
  const parent = resolve(root, parentPointer);
  if (Array.isArray(parent)) {
    parent.splice(Number(token), 1);
  } else {
    delete parent[token];
  }
  return root;
}

/**
 * Replace the value at a pointer, which must already exist.
 *
 * @param {unknown} root the document to mutate
 * @param {string} path pointer to replace
 * @param {unknown} value the (already cloned) replacement value
 * @returns {unknown} the (possibly new) root
 */
function performReplace(root, path, value) {
  const tokens = parsePointer(path);
  if (tokens.length === 0) return value;
  resolve(root, path);
  const token = tokens[tokens.length - 1];
  const parentPointer = formatPointer(tokens.slice(0, -1));
  const parent = resolve(root, parentPointer);
  if (Array.isArray(parent)) {
    parent[Number(token)] = value;
  } else {
    setProperty(parent, token, value);
  }
  return root;
}

/**
 * Check whether one token list is a proper prefix of another.
 *
 * @param {string[]} a candidate prefix
 * @param {string[]} b the longer list
 * @returns {boolean} whether `a` is a proper prefix of `b`
 */
function isProperPrefix(a, b) {
  return a.length < b.length && a.every((token, index) => token === b[index]);
}

/**
 * Move the value at `from` to `path`.
 *
 * @param {unknown} root the document to mutate
 * @param {string} from pointer to the value to move
 * @param {string} path pointer to move it to
 * @returns {unknown} the (possibly new) root
 */
function performMove(root, from, path) {
  const fromTokens = parsePointer(from);
  const pathTokens = parsePointer(path);
  const fromPointer = formatPointer(fromTokens);
  const pathPointer = formatPointer(pathTokens);
  if (fromPointer === pathPointer) return root;
  if (isProperPrefix(fromTokens, pathTokens)) {
    throw new Error('cannot move a value into its own child');
  }
  const value = cloneJSON(resolve(root, fromPointer));
  const afterRemove = performRemove(root, fromPointer);
  return performAdd(afterRemove, pathPointer, value);
}

/**
 * Copy the value at `from` to `path`.
 *
 * @param {unknown} root the document to mutate
 * @param {string} from pointer to the value to copy
 * @param {string} path pointer to add the copy at
 * @returns {unknown} the (possibly new) root
 */
function performCopy(root, from, path) {
  const value = cloneJSON(resolve(root, from));
  return performAdd(root, path, value);
}

/**
 * Compare the value at a pointer with an expected value.
 *
 * @param {unknown} root the document to check
 * @param {string} path pointer to the value under test
 * @param {unknown} value the expected value
 * @returns {unknown} the root, unchanged
 */
function performTest(root, path, value) {
  const actual = resolve(root, path);
  if (!jsonEqual(actual, value)) {
    throw new Error(`test failed at ${path}`);
  }
  return root;
}

/**
 * Apply one already-validated operation to a mutable working document.
 *
 * @param {unknown} root the document to mutate
 * @param {object} operation the operation to apply
 * @returns {unknown} the (possibly new) root
 */
function applyOperation(root, operation) {
  validateOperation(operation);
  const { op, path, from } = operation;
  switch (op) {
    case 'add':
      return performAdd(root, path, cloneJSON(checkValue(operation.value)));
    case 'remove':
      return performRemove(root, path);
    case 'replace':
      return performReplace(root, path, cloneJSON(checkValue(operation.value)));
    case 'move':
      return performMove(root, from, path);
    case 'copy':
      return performCopy(root, from, path);
    case 'test':
      return performTest(root, path, checkValue(operation.value));
    default:
      throw new Error(`unknown operation: ${op}`);
  }
}

/**
 * Apply a patch, leaving the input untouched whether or not it succeeds.
 *
 * @param {unknown} document JSON data to patch
 * @param {object[]} operations the patch
 * @returns {unknown} a new document with every operation applied
 */
export function applyPatch(document, operations) {
  if (!isJsonData(document)) {
    throw new Error('document is not JSON data');
  }
  if (!Array.isArray(operations)) {
    throw new Error('patch must be an array');
  }
  let root = cloneJSON(document);
  operations.forEach((operation, index) => {
    try {
      root = applyOperation(root, operation);
    } catch (error) {
      if (error instanceof PointerError) {
        throw new PatchError(error.message, index, { cause: error });
      }
      throw new PatchError(error.message, index);
    }
  });
  return root;
}
"}

