/** Failure raised anywhere in the expression pipeline. */
export class ExprError extends Error {
  /**
   * @param {string} message reason, ending with the position it refers to
   * @param {number} index 0-based index into the source, in UTF-16 code units
   */
  constructor(message, index) {
    super(message);
    this.name = 'ExprError';
    this.index = index;
  }
}

const NAME_START = /[A-Za-z_]/;
const NAME_CHAR = /[A-Za-z0-9_]/;
const DIGIT = /[0-9]/;
const NUM_RE = /^(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?/;
const GLUED_CHAR = /[A-Za-z0-9_.]/;
const OPERATORS = new Set(['+', '-', '*', '/', '%', '^']);

/**
 * Split an expression into tokens.
 *
 * @param {string} input expression source
 * @returns {{ type: 'number' | 'name' | 'operator' | 'lparen' | 'rparen' | 'comma', value: number | string, index: number }[]}
 *   tokens in source order
 */
export function tokenize(input) {
  const tokens = [];
  let i = 0;
  const length = input.length;

  while (i < length) {
    const ch = input[i];

    if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\v' || ch === '\f') {
      i += 1;
      continue;
    }

    const startsNumber = DIGIT.test(ch) || (ch === '.' && DIGIT.test(input[i + 1] || ''));
    if (startsNumber) {
      const start = i;
      const rest = input.slice(i);
      const match = NUM_RE.exec(rest);
      const matched = match ? match[0] : '';
      const nextIndex = start + matched.length;
      const nextChar = input[nextIndex];
      if (matched.length === 0 || (nextChar !== undefined && GLUED_CHAR.test(nextChar))) {
        throw new ExprError(`malformed number at ${start}`, start);
      }
      tokens.push({ type: 'number', value: Number(matched), index: start });
      i = nextIndex;
      continue;
    }

    if (NAME_START.test(ch)) {
      const start = i;
      let j = i + 1;
      while (j < length && NAME_CHAR.test(input[j])) j += 1;
      tokens.push({ type: 'name', value: input.slice(start, j), index: start });
      i = j;
      continue;
    }

    if (OPERATORS.has(ch)) {
      tokens.push({ type: 'operator', value: ch, index: i });
      i += 1;
      continue;
    }

    if (ch === '(') {
      tokens.push({ type: 'lparen', value: '(', index: i });
      i += 1;
      continue;
    }

    if (ch === ')') {
      tokens.push({ type: 'rparen', value: ')', index: i });
      i += 1;
      continue;
    }

    if (ch === ',') {
      tokens.push({ type: 'comma', value: ',', index: i });
      i += 1;
      continue;
    }

    const codePoint = input.codePointAt(i);
    const char = String.fromCodePoint(codePoint);
    throw new ExprError(`unexpected character '${char}' at ${i}`, i);
  }

  return tokens;
}
"}

