import { ExprError, tokenize } from './tokenize.js';

/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  let pos = 0;

  const peek = () => tokens[pos];
  const advance = () => tokens[pos++];

  const unexpectedEnd = () => {
    throw new ExprError(`unexpected end of input at ${input.length}`, input.length);
  };

  const unexpectedToken = (token) => {
    throw new ExprError(`unexpected token '${token.value}' at ${token.index}`, token.index);
  };

  function parseExpression() {
    return parseAdditive();
  }

  function parseAdditive() {
    let left = parseMultiplicative();
    while (peek() && peek().type === 'operator' && (peek().value === '+' || peek().value === '-')) {
      const opToken = advance();
      const right = parseMultiplicative();
      left = { type: 'binary', op: opToken.value, left, right, index: opToken.index };
    }
    return left;
  }

  function parseMultiplicative() {
    let left = parseUnary();
    while (peek() && peek().type === 'operator' && (peek().value === '*' || peek().value === '/' || peek().value === '%')) {
      const opToken = advance();
      const right = parseUnary();
      left = { type: 'binary', op: opToken.value, left, right, index: opToken.index };
    }
    return left;
  }

  function parseUnary() {
    const token = peek();
    if (token && token.type === 'operator' && (token.value === '+' || token.value === '-')) {
      advance();
      const operand = parseUnary();
      return { type: 'unary', op: token.value, operand, index: token.index };
    }
    return parsePower();
  }

  function parsePower() {
    const base = parsePrimary();
    const token = peek();
    if (token && token.type === 'operator' && token.value === '^') {
      advance();
      const exponent = parseUnary();
      return { type: 'binary', op: '^', left: base, right: exponent, index: token.index };
    }
    return base;
  }

  function parseCallArgs() {
    const args = [];
    if (peek() && peek().type === 'rparen') {
      advance();
      return args;
    }
    for (;;) {
      args.push(parseExpression());
      const token = peek();
      if (!token) unexpectedEnd();
      if (token.type === 'comma') {
        advance();
        continue;
      }
      if (token.type === 'rparen') {
        advance();
        return args;
      }
      unexpectedToken(token);
    }
  }

  function parsePrimary() {
    const token = peek();
    if (!token) unexpectedEnd();

    if (token.type === 'number') {
      advance();
      return { type: 'number', value: token.value, index: token.index };
    }

    if (token.type === 'name') {
      advance();
      if (peek() && peek().type === 'lparen') {
        advance();
        const args = parseCallArgs();
        return { type: 'call', name: token.value, args, index: token.index };
      }
      return { type: 'variable', name: token.value, index: token.index };
    }

    if (token.type === 'lparen') {
      advance();
      const inner = parseExpression();
      const closing = peek();
      if (closing && closing.type === 'rparen') {
        advance();
        return inner;
      }
      const index = closing ? closing.index : input.length;
      throw new ExprError(`missing closing parenthesis at ${index}`, index);
    }

    return unexpectedToken(token);
  }

  const tree = parseExpression();
  if (pos < tokens.length) {
    unexpectedToken(tokens[pos]);
  }
  return tree;
}
"}

{"file_path":"src/index.js","content":"/**
 * Arithmetic expression evaluator: tokeniser, precedence-climbing parser and a
 * tree walker with named constants, variables and a fixed function table.
 */

import { ExprError, tokenize } from './tokenize.js';
import { parse } from './parse.js';

export { ExprError, tokenize, parse };

const CONSTANTS = { pi: Math.PI, e: Math.E };

const FUNCTIONS = {
  abs: { arity: 1, impl: Math.abs },
  sqrt: { arity: 1, impl: Math.sqrt },
  floor: { arity: 1, impl: Math.floor },
  ceil: { arity: 1, impl: Math.ceil },
  round: { arity: 1, impl: Math.round },
  sign: { arity: 1, impl: Math.sign },
  pow: { arity: 2, impl: Math.pow },
  atan2: { arity: 2, impl: Math.atan2 },
  min: { arity: 'variadic', impl: (...args) => Math.min(...args) },
  max: { arity: 'variadic', impl: (...args) => Math.max(...args) },
};

function resolveVariable(name, index, env) {
  let value;
  if (Object.prototype.hasOwnProperty.call(env, name)) {
    value = env[name];
  } else if (Object.prototype.hasOwnProperty.call(CONSTANTS, name)) {
    value = CONSTANTS[name];
  } else {
    throw new ExprError(`unknown variable: ${name} at ${index}`, index);
  }
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new ExprError(`variable ${name} is not a finite number at ${index}`, index);
  }
  return value;
}

function checkArity(name, spec, got, index) {
  if (spec === 'variadic') {
    if (got < 1) {
      throw new ExprError(`function ${name} expects at least 1 argument, got ${got} at ${index}`, index);
    }
    return;
  }
  if (got !== spec) {
    const word = spec === 1 ? 'argument' : 'arguments';
    throw new ExprError(`function ${name} expects ${spec} ${word}, got ${got} at ${index}`, index);
  }
}

function evalCall(node, env) {
  const definition = FUNCTIONS[node.name];
  if (!definition) {
    throw new ExprError(`unknown function: ${node.name} at ${node.index}`, node.index);
  }
  const args = node.args.map((arg) => evalNode(arg, env));
  checkArity(node.name, definition.arity, args.length, node.index);
  const result = definition.impl(...args);
  if (typeof result !== 'number' || !Number.isFinite(result)) {
    throw new ExprError(`non-finite result at ${node.index}`, node.index);
  }
  return result;
}

function evalBinary(node, env) {
  const left = evalNode(node.left, env);
  const right = evalNode(node.right, env);
  let result;
  switch (node.op) {
    case '+':
      result = left + right;
      break;
    case '-':
      result = left - right;
      break;
    case '*':
      result = left * right;
      break;
    case '/':
      if (right === 0) throw new ExprError(`division by zero at ${node.index}`, node.index);
      result = left / right;
      break;
    case '%':
      if (right === 0) throw new ExprError(`division by zero at ${node.index}`, node.index);
      result = left % right;
      break;
    case '^':
      result = left ** right;
      break;
    default:
      throw new ExprError(`unexpected operator '${node.op}' at ${node.index}`, node.index);
  }
  if (!Number.isFinite(result)) {
    throw new ExprError(`non-finite result at ${node.index}`, node.index);
  }
  return result;
}

function evalNode(node, env) {
  switch (node.type) {
    case 'number':
      return node.value;
    case 'variable':
      return resolveVariable(node.name, node.index, env);
    case 'unary':
      return node.op === '-' ? -evalNode(node.operand, env) : evalNode(node.operand, env);
    case 'binary':
      return evalBinary(node, env);
    case 'call':
      return evalCall(node, env);
    default:
      throw new ExprError(`unexpected node '${node.type}' at ${node.index}`, node.index);
  }
}

/**
 * Evaluate an expression.
 *
 * @param {string} input expression source
 * @param {Record<string, number>} [env] variable bindings, shadowing the built-in constants
 * @returns {number} the finite result
 */
export function evaluate(input, env = {}) {
  const tree = parse(input);
  return evalNode(tree, env);
}
"}

