{"file_path":"src/expand.js","content":"/** URI template expansion following the operator table. */

import { UriTemplateError, parse } from './parse.js';

const UNRESERVED_RE = /[A-Za-z0-9\-._~]/;
const RESERVED_RE = /[:/?#[\]@!$&'()*+,;=]/;
const HEX_TRIPLET_RE = /^%[0-9A-Fa-f]{2}/;

const OPERATORS = {
  '': { prefix: '', sep: ',', named: false, ifemp: '', reserved: false },
  '+': { prefix: '', sep: ',', named: false, ifemp: '', reserved: true },
  '#': { prefix: '#', sep: ',', named: false, ifemp: '', reserved: true },
  '.': { prefix: '.', sep: '.', named: false, ifemp: '', reserved: false },
  '/': { prefix: '/', sep: '/', named: false, ifemp: '', reserved: false },
  ';': { prefix: ';', sep: ';', named: true, ifemp: '', reserved: false },
  '?': { prefix: '?', sep: '&', named: true, ifemp: '=', reserved: false },
  '&': { prefix: '&', sep: '&', named: true, ifemp: '=', reserved: false },
};

function percentEncodeChar(ch) {
  const bytes = Buffer.from(ch, 'utf8');
  let out = '';
  for (const b of bytes) out += `%${b.toString(16).toUpperCase().padStart(2, '0')}`;
  return out;
}

/** Encode keeping unreserved characters, reserved characters and existing percent-triplets. */
function encodeKeepingReserved(str) {
  let result = '';
  let i = 0;
  while (i < str.length) {
    const rest = str.slice(i);
    const m = HEX_TRIPLET_RE.exec(rest);
    if (m) {
      result += m[0];
      i += 3;
      continue;
    }
    const codePoint = str.codePointAt(i);
    const ch = String.fromCodePoint(codePoint);
    if (UNRESERVED_RE.test(ch) || RESERVED_RE.test(ch)) {
      result += ch;
    } else {
      result += percentEncodeChar(ch);
    }
    i += ch.length;
  }
  return result;
}

/** Encode keeping only unreserved characters, everything else including `%` is encoded. */
function encodeUnreservedOnly(str) {
  let result = '';
  let i = 0;
