      const encodedKey = encode(key, info.keepReserved);
      const encodedVal = encode(String(v), info.keepReserved);
      if (info.named && encodedVal === '') {
        return `${encodedKey}${info.emptyText}`;
      }
      return `${encodedKey}=${encodedVal}`;
    });
  }
