    encode(key, info.keepReserved),
    encode(String(v), info.keepReserved),
  ]);
  const joined = flat.join(',');
  return [info.named ? `${name}=${joined}` : joined];
}

function expandExpression(part, variables) {
  const info = OPERATOR_INFO[part.operator];
  const pieces = [];
  for (const spec of part.variables) {
    const has = Object.prototype.hasOwnProperty.call(variables, spec.name);
    const value = has ? variables[spec.name] : undefined;
    const result = expandVariable(spec, value, info);
