{"file_path":"src/trie.js","content":"/**
 * Prefix index over Unicode strings.
 *
 * Words are stored one code point per edge, so a character outside the
 * basic multilingual plane (e.g. an emoji) is a single step rather than a
 * pair of surrogate halves. Every node keeps a count of the words stored in
 * its subtree so prefix counts are O(prefix length) rather than a subtree
 * walk.
 */

/**
 * A single trie node.
 */
class TrieNode {
  constructor() {
    /** @type {Map<string, TrieNode>} Children keyed by a single code point. */
    this.children = new Map();
    /** @type {boolean} Whether a word ends at this node. */
    this.isWord = false;
    /** @type {unknown} Value stored when isWord is true. */
    this.value = undefined;
    /** @type {number} Number of words stored in this node's subtree. */
    this.count = 0;
  }
}

/**
 * Validates that a value is a string.
 * @param {unknown} value Value to check.
 * @param {string} name Argument name used in the error message.
 * @returns {void}
 */
function assertString(value, name) {
  if (typeof value !== 'string') {
    throw new TypeError(`${name} must be a string`);
  }
}

/**
 * Validates a search limit.
 * @param {unknown} limit Value to check.
 * @returns {void}
 */
function assertLimit(limit) {
  const valid =
    limit === Number.POSITIVE_INFINITY ||
    (typeof limit === 'number' && Number.isSafeInteger(limit) && limit >= 0);
  if (!valid) {
    throw new TypeError('limit must be a non-negative integer');
  }
}

/**
 * Splits a string into an array of single code points.
 * @param {string} value String to split.
 * @returns {string[]} Code points, in order.
 */
function codePoints(value) {
  return [...value];
}

/**
 * Compares two single code point strings by code point value.
 * @param {string} a First code point.
 * @param {string} b Second code point.
 * @returns {number} Negative, zero, or positive.
 */
function compareCodePoint(a, b) {
  return a.codePointAt(0) - b.codePointAt(0);
}

export class Trie {
  #root = new TrieNode();
  #size = 0;
  #nodeCount = 1;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#size;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#nodeCount;
  }

  /**
   * Walks the trie following the code points of a string.
   * @param {string} word Word to walk.
   * @returns {TrieNode | null} Node reached, or null if the path is missing.
   */
  #walk(word) {
    let node = this.#root;
    for (const ch of codePoints(word)) {
      const next = node.children.get(ch);
      if (!next) return null;
      node = next;
    }
    return node;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    assertString(word, 'word');
    const path = [this.#root];
    let node = this.#root;
    for (const ch of codePoints(word)) {
      let next = node.children.get(ch);
      if (!next) {
        next = new TrieNode();
        node.children.set(ch, next);
        this.#nodeCount += 1;
      }
      node = next;
      path.push(node);
    }
    const previous = node.isWord ? node.value : undefined;
    if (!node.isWord) {
      for (const n of path) n.count += 1;
      this.#size += 1;
    }
    node.isWord = true;
    node.value = value;
    return previous;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    assertString(word, 'word');
    const node = this.#walk(word);
    return node && node.isWord ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    assertString(word, 'word');
    const node = this.#walk(word);
    return Boolean(node && node.isWord);
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    assertString(word, 'word');
    const chars = codePoints(word);
    const path = [this.#root];
    let node = this.#root;
    for (const ch of chars) {
      const next = node.children.get(ch);
      if (!next) return false;
      node = next;
      path.push(node);
    }
    if (!node.isWord) return false;

    node.isWord = false;
    node.value = undefined;
    for (const n of path) n.count -= 1;
    this.#size -= 1;

    for (let i = path.length - 1; i > 0; i -= 1) {
      const current = path[i];
      if (current.isWord || current.children.size > 0) break;
      const parent = path[i - 1];
      parent.children.delete(chars[i - 1]);
      this.#nodeCount -= 1;
    }

    return true;
  }

  /**
   * Counts the stored words that start with a prefix.
   * @param {string} prefix Prefix to count under.
   * @returns {number} Number of words with that prefix.
   */
  countPrefix(prefix) {
    assertString(prefix, 'prefix');
    const node = this.#walk(prefix);
    return node ? node.count : 0;
  }

  /**
   * Collects [word, value] pairs from a node's subtree, in code point order.
   * @param {TrieNode} node Node to start from.
   * @param {string} prefix Word accumulated so far.
   * @param {number} limit Maximum number of pairs to collect.
   * @param {Array<[string, unknown]>} out Accumulator.
   * @returns {void}
   */
  #collect(node, prefix, limit, out) {
    if (out.length >= limit) return;
    if (node.isWord) {
      out.push([prefix, node.value]);
      if (out.length >= limit) return;
    }
    const children = [...node.children.entries()].sort((a, b) => compareCodePoint(a[0], b[0]));
    for (const [ch, child] of children) {
      this.#collect(child, prefix + ch, limit, out);
      if (out.length >= limit) return;
    }
  }

  /**
   * Lists the stored words that start with a prefix, in code point order.
   * @param {string} prefix Prefix to search under.
   * @param {number} [limit] Maximum number of words to return.
   * @returns {string[]} Matching words.
   */
  search(prefix, limit = Number.POSITIVE_INFINITY) {
    assertString(prefix, 'prefix');
    assertLimit(limit);
    const node = this.#walk(prefix);
    if (!node || limit === 0) return [];
    const out = [];
    this.#collect(node, prefix, limit, out);
    return out.map(([word]) => word);
  }

  /**
   * Lists every stored word with its value, in code point order.
   * @returns {Array<[string, unknown]>} Word and value pairs.
   */
  entries() {
    const out = [];
    this.#collect(this.#root, '', Number.POSITIVE_INFINITY, out);
    return out;
  }

  /**
   * Finds the longest stored word that is a prefix of the text.
   * @param {string} text Text to match against.
   * @returns {{word: string, value: unknown} | null} Longest match, or null.
   */
  longestPrefixMatch(text) {
    assertString(text, 'text');
    let node = this.#root;
    let best = node.isWord ? { word: '', value: node.value } : null;
    let prefix = '';
    for (const ch of codePoints(text)) {
      const next = node.children.get(ch);
      if (!next) break;
      node = next;
      prefix += ch;
      if (node.isWord) best = { word: prefix, value: node.value };
    }
    return best;
  }
}
