      return { type: 'unary', op: token.value, operand, index: token.index };
    }

    if (token.type === 'lparen') {
      pos += 1;
      const inner = parseExpression(1);
      expectMore();
      if (tokens[pos].type !== 'rparen') {
        throw new ExprError(`missing closing parenthesis at ${tokens[pos].index}`, tokens[pos].index);
      }
      pos += 1;
      return inner;
    }

    if (token.type === 'name') {
      pos += 1;
      if (pos < tokens.length && tokens[pos].type === 'lparen') {
        pos += 1;
        const args = [];
        if (pos < tokens.length && tokens[pos].type === 'rparen') {
          pos += 1;
        } else {
          while (true) {
            args.push(parseExpression(1));
            expectMore();
            if (tokens[pos].type === 'comma') {
              pos += 1;
              continue;
            }
            if (tokens[pos].type === 'rparen') {
              pos += 1;
              break;
            }
            throw new ExprError(
              `unexpected token '${describeToken(tokens[pos])}' at ${tokens[pos].index}`,
              tokens[pos].index,
            );
          }
        }
        return { type: 'call', name: token.value, args, index: token.index };
      }
      return { type: 'variable', name: token.value, index: token.index };
    }

    throw new ExprError(`unexpected token '${describeToken(token)}' at ${token.index}`, token.index);
  }

  function parseUnary() {
    return parsePrimary();
  }

  function parsePower() {
    const base = parseUnary();
    if (pos < tokens.length && tokens[pos].type === 'operator' && tokens[pos].value === '^') {
      const opToken = tokens[pos];
      pos += 1;
      const right = parsePower();
      return { type: 'binary', op: '^', left: base, right, index: opToken.index };
    }
    return base;
  }

  function parseExpression(minPrecedence) {
    let left = parsePower();

    while (
      pos < tokens.length &&
      tokens[pos].type === 'operator' &&
      tokens[pos].value !== '^' &&
      BINARY_PRECEDENCE[tokens[pos].value] >= minPrecedence
    ) {
      const opToken = tokens[pos];
      const level = BINARY_PRECEDENCE[opToken.value];
      pos += 1;
      const right = parseExpression(level + 1);
      left = { type: 'binary', op: opToken.value, left, right, index: opToken.index };
    }

    return left;
  }

  if (tokens.length === 0) {
    throw new ExprError(`unexpected end of input at 0`, 0);
  }

  const tree = parseExpression(1);

  if (pos < tokens.length) {
    const token = tokens[pos];
    throw new ExprError(`unexpected token '${describeToken(token)}' at ${token.index}`, token.index);
  }

  return tree;
}
"}

